/* @lc app=leetcode id=993 lang=kotlin */ class Solution { fun isCousins(root: TreeNode?, x: Int, y: Int): Boolean = generateSequence(listOf(root!! to (null as TreeNode?))) { f -> f.flatMap { (n, _) -> listOfNotNull(n.left, n.right).map { it to (n as TreeNode?) } }.takeIf { it.isNotEmpty() } }.any { l -> l.filter { it.first.`val` == x || it.first.`val` == y }.let { it.size == 2 && it[0].second !== it[1].second } } }